'use strict';
const KEY='rook43-prototype-v1';
let state=Rook.initial();try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.schema===1&&Rook.scenarios[saved.scenario])state=saved;}catch{}
const $=id=>document.getElementById(id);
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=t=>'Demo day 1 · '+new Date(Date.UTC(2026,8,7,9,0,t)).toISOString().slice(11,19);
const score=()=>state.score===null?'Unavailable':state.score.toFixed(2);
const review=()=>({none:'No review requested',requested:'Review requested · R-43-F',needed:'Review needed',preview:'Adjustment awaiting approval',applied:'Recovery adjustment applied','not-needed':'No adjustment needed'}[state.review]);
const btn=(action,text,secondary=false)=>`<button data-act="${action}" class="${secondary?'secondary':''}">${text}</button>`;
const weeks=[['Jun 29',12,9],['Jul 06',12,9],['Jul 13',11,8],['Jul 20',12,9],['Jul 27',13,10],['Aug 03',12,8],['Aug 10',10,4],['Aug 17',3,0],['Aug 24',1,0],['Aug 31',0,0]];
function availability(){return `${state.engaged?'Engaged · ':''}${state.available?'Available':'Unavailable'}`;}
function history(){return `<details><summary>Open all 10 weeks & Linda’s support concern</summary><table><thead><tr><th>Week starting · 2026</th><th>Offered</th><th>Taken</th></tr></thead><tbody>${weeks.map(w=>`<tr><td>${w[0]}${w[0]==='Aug 10'?' · release week':''}</td><td>${w[1]}</td><td>${w[2]}</td></tr>`).join('')}</tbody></table><p class="source">Verified Module 3 rows. August 10 week straddles release: before Aug 12, 3 offered / 2 taken; from Aug 12, 7 / 2. Exact rollout time is unknown.</p><blockquote>“I have checked her availability and everything is set to available.”</blockquote><p class="source">Linda Pruitt · support ticket #3130 · September 3, 2026. Earlier tickets #3060 and #3110 describe silence and an offer expiring.</p><p>No candidate snapshots establish exactly why Farlight was skipped.</p></details>`;}
function repairCard(){return `<h3>Recovery review</h3><span class="tag ${state.review==='needed'?'warn':''}">${review()}</span><p>${state.repair?'An approved adjustment was saved. Future offers still depend on the callout and other responders.':'A review can address a historical disadvantage. It cannot reconstruct an unknown starting score or promise a job.'}</p>`;}
function routing(){const c=state.call;if(!c)return `<div class="empty"><h3>No active callout</h3><p>Create a simulated Uptown callout in the Demo Studio to inspect who gets asked.</p></div>`;
return `<div class="card route"><div class="eyebrow">SIMULATED CALLOUT ${c.id} · ALL INPUTS SIMULATED</div><h2>${c.name}</h2><span class="tag">${c.status==='assigned'?'Assigned to '+c.assignee:c.status==='unassigned'?'Unassigned · escalate':'Awaiting '+c.offer.name+' · '+(c.offer.deadline-state.now)+' sec'}</span><table><thead><tr><th>Rank / candidate</th><th>Travel</th><th>Proximity × .60</th><th>History × .25</th><th>Match × .15</th><th>Total</th></tr></thead><tbody>${c.candidates.map((p,i)=>`<tr class="${i===c.index?'active-row':''}"><td>${i+1}. ${p.name}</td><td>${p.travel} min</td><td>${(.6*Math.max(0,1-p.travel/45)).toFixed(3)}</td><td>${p.history.toFixed(2)} × .25</td><td>100% × .15</td><td><b>${p.total.toFixed(3)}</b></td></tr>`).join('')}</tbody></table><p class="small">Snapshot at routing time. Formula matches routing.py: proximity falls linearly to zero at 45 minutes. Both candidates are available in Uptown with full capability match. Unavailable Farlight is excluded.</p>${c.outcomes.map(o=>`<p class="small">${o.name}: ${o.outcome} · ${o.id}</p>`).join('')}<p class="small">${c.status==='assigned'?`Time to assignment: ${c.assignedAt-c.started} simulated seconds.`:'Routing waits at most 60 seconds per offer, then advances.'}</p></div>`;}
function linda(){return `<div class="card"><div class="card-top"><div class="identity"><div class="avatar">F</div><div><h2>Farlight</h2><p>Uptown · managed by Linda Pruitt</p></div></div><span class="tag">${availability()}</span></div><div class="metrics"><div class="metric"><small>Recorded week Aug 31–Sep 6</small><strong>0</strong><small>offers received</small></div><div class="metric"><small>Before release week</small><strong>11–13</strong><small>offers per week</small></div><div class="metric"><small>Last readiness confirmation</small><strong style="font-size:17px">${state.confirmed===null?'Not recorded':clock(state.confirmed)}</strong><small>simulated live record</small></div></div><div class="notice"><b>No offers recorded in the last seven days of the historical dataset.</b><p>Availability was reported as correct. Why she was skipped: information unavailable.</p></div><div class="bars" aria-label="Historical weekly offers and acceptances">${weeks.map(w=>`<div class="bar-group"><div class="bar-pair"><div class="bar" style="height:${w[1]*8}px" title="${w[1]} offered"></div><div class="bar taken" style="height:${w[2]*8}px" title="${w[2]} taken"></div></div><small>${w[0]}</small></div>`).join('')}</div><p class="source">Gray: offered · Green: taken. Historical evidence, not today’s live totals.</p>${history()}</div><div class="two"><div class="card">${repairCard()}${btn('request',state.review==='none'?'Request support review':'Check / repeat review request')}</div><div class="card"><h3>Readiness</h3><p>Saved status: <b>${availability()}</b></p><p>Linda may manage availability for Farlight. A readiness change does not change her score.</p><div class="actions">${btn('available','Mark available')}${btn('unavailable','Mark unavailable',true)}</div></div></div><div style="margin-top:18px">${routing()}</div>`;}
function phone(){const c=state.call,o=c?.offer;const incoming=c?.status==='offered'&&o.name==='Farlight';return `<div class="phone"><div class="phone-head"><small>ROOK DISPATCH / RESPONDER</small><h2>Hello, Farlight.</h2><span class="tag">${availability()}</span></div><div class="phone-body">${incoming?`<div class="card incoming"><div class="eyebrow">INCOMING OFFER · SIMULATED</div><h3>Cedar Arcade</h3><p>Fallen masonry · Uptown<br>8 min estimated travel · capability match</p><div class="countdown">${o.deadline-state.now}s</div><p class="small">Remaining to answer</p>${btn('accept','Take this job')}${btn('decline','Decline',true)}</div>`:c?.status==='assigned'?`<div class="notice"><b>${c.assignee==='Farlight'?'Job assigned to you':'Callout assigned to '+c.assignee}</b><p>${c.assignee==='Farlight'?'Your acceptance is saved. You are engaged.':'You may receive a future offer. No offer is guaranteed.'}</p></div>`:`<div class="empty"><h3>Waiting for your next offer</h3><p>Your readiness is visible. Offers depend on the next callout and its ranking.</p></div>`}${state.prompt?.status==='delivered'?`<div class="notice"><h3>Still available?</h3><p>We recorded three delivered offers without a reply. Please check your availability. You have not been paused.</p></div>`:''}<div class="card" style="margin-top:16px"><h3>Your availability</h3><p class="small">${state.confirmed===null?'No confirmation recorded':`Confirmed ${clock(state.confirmed)}`}</p>${btn('available','I’m available')}${btn('unavailable','Mark unavailable',true)}${btn('reload','Reload latest status',true)}</div><div class="card">${repairCard()}</div></div></div>`;}
function operator(){return `<div class="card"><div class="eyebrow">AUTHORIZED RECOVERY OPERATOR · DEMO ROLE</div><h2>Farlight / recovery review</h2><p>Review R-43-F · ${review()}</p><div class="notice">Bounded neutral-score repair. This is not a reconstruction of Farlight’s historical score.</div><div class="metrics"><div class="metric"><small>Stored score · simulated</small><strong>${score()}</strong></div><div class="metric"><small>Score version</small><strong>${state.sv}</strong></div><div class="metric"><small>Approved policy target</small><strong>0.50</strong><small>proposed, awaiting Helen</small></div></div>${history()}${state.preview?`<div class="score-change">${state.preview.score.toFixed(2)} <span>→</span> 0.50</div><p>Preview version ${state.preview.version}. Approval checks that the stored version still matches.</p>`:''}<div class="actions">${btn('preview','Preview adjustment')}${btn('approve',state.repair?'Check original repair result':'Approve adjustment')}</div><p class="small">No self-service score changes. Role checks are simulated in this local app; production authorization requires a server.</p></div><div class="card"><h3>Repair audit</h3>${state.audit.length?state.audit.map(a=>`<p><span class="tag">Committed once</span></p><p><b>${a.before.toFixed(2)} → ${a.after.toFixed(2)}</b> · ${clock(a.time)}</p><p class="small">${a.id} · ${a.actor}<br>Reviewed version ${a.version} · ${a.evidence}</p>`).join(''):'<p>No committed adjustment. Previews and failed saves do not appear as success.</p>'}</div>${routing()}`;}
function render(){
 $('actors').innerHTML=[['linda','01','Linda Pruitt','Handler console'],['farlight','02','Farlight','Responder phone'],['operator','03','Recovery operator','Authorized review']].map(([id,n,name,role])=>`<button data-actor="${id}" class="${state.actor===id?'active':''}" aria-pressed="${state.actor===id}">${n} &nbsp; ${name}<small>${role}${state.actor===id?' · signed in':''}</small></button>`).join('');
 $('feedback').textContent=state.message;$('screen').innerHTML=state.actor==='linda'?linda():state.actor==='farlight'?phone():operator();
 $('scenario').innerHTML=Object.entries(Rook.scenarios).map(([id,[name]])=>`<option value="${id}" ${state.scenario===id?'selected':''}>${name}</option>`).join('');
 $('scenarioHelp').textContent=Rook.scenarios[state.scenario][1];$('clock').textContent=clock(state.now);$('receipt').value=state.receipt;
 $('debug').innerHTML=`<b>Shared simulation state</b><br>Score ${score()} · version ${state.sv}<br>Qualifying misses: ${state.misses.length} / 3<br>Prompt: ${state.prompt?`${state.prompt.status} · ${state.prompt.id} · attempt ${state.prompt.attempts}`:'none'}<br>Cooldown: ${Math.max(0,state.cooldown-state.now)} seconds<br>Availability version: ${state.av} · open action: ${state.viewAv}`;
 $('events').innerHTML=state.events.length?state.events.map(e=>`<li><time>${clock(e.time)}</time>${esc(e.text)}</li>`).join(''):'<li>Your actions will appear here. Start by requesting a review as Linda.</li>';
}
function send(a){const old=state;state=Rook.step(state,a);try{localStorage.setItem(KEY,JSON.stringify(state));}catch{state=old;state.message='Browser storage could not save the action. No success acknowledged. Enable storage and retry.';}render();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.actor){send({type:'ACTOR',actor:b.dataset.actor});return;}const action=b.dataset.act;const actions={request:{type:'REQUEST'},available:{type:'AVAILABLE',value:true},unavailable:{type:'AVAILABLE',value:false},reload:{type:'RELOAD'},preview:{type:'PREVIEW'},approve:{type:'APPROVE'},callout:{type:'CALLOUT'},accept:{type:'ANSWER',value:'taken',offerId:state.call?.offer?.id},decline:{type:'ANSWER',value:'turned down',offerId:state.call?.offer?.id},other:{type:'ANSWER',value:'taken',demo:true,offerId:state.call?.offer?.id},tick30:{type:'TICK',seconds:30},tick60:{type:'TICK',seconds:60},tickHour:{type:'TICK',seconds:3600},concurrent:{type:'CONCURRENT'},newer:{type:'NEWER_UNAVAILABLE'},retryPrompt:{type:'RETRY_PROMPT'},complete:{type:'COMPLETE'},failAvailability:{type:'AVAILABLE',value:true,fail:true}};
 if(action==='other'&&state.call?.offer?.name!=='Beacon'){state.message='Beacon has no active offer. Let routing reach Beacon first.';render();return;}
 if(action==='double'){send({type:'APPROVE'});send({type:'APPROVE'});}else if(actions[action])send(actions[action]);
});
$('scenario').addEventListener('change',e=>send({type:'RESET',scenario:e.target.value}));$('receipt').addEventListener('change',e=>send({type:'RECEIPT',value:e.target.value}));$('reset').addEventListener('click',()=>send({type:'RESET'}));
render();
